function i(){const t=document.querySelector("[data-accordion]");if(!t)return;const o=Array.from(t.querySelectorAll(".accordion__trigger"));o.forEach(e=>{const a=t.querySelector(`#${e.getAttribute("aria-controls")}`);a&&e.addEventListener("click",()=>{const n=e.getAttribute("aria-expanded")==="true";o.forEach(r=>{r!==e&&(r.setAttribute("aria-expanded","false"),t.querySelector(`#${r.getAttribute("aria-controls")}`)?.classList.remove("is-open"))}),e.setAttribute("aria-expanded",String(!n)),a.classList.toggle("is-open",!n)})})}export{i as init};
